function o(t){return new Intl.DateTimeFormat("en-US",{timeZone:"UTC",year:"numeric",month:"long",day:"numeric"}).format(new Date(`${t}T00:00:00Z`))}function n(t){return new Intl.NumberFormat("en-US",{maximumFractionDigits:0}).format(Math.floor(t))}function r(t){if(t<1e3)return`${Math.floor(t)}`;if(t<1e5){const e=Math.floor(t/100)/10;return Number.isInteger(e)?`${e}k`:`${e.toFixed(1)}k`}return`${Math.floor(t/1e3)}k`}export{n as a,o as b,r as f};
